public:
    int findSubstringInWraproundString(string s) {
        int best[26] = {0}, run = 0;
        for (int i = 0; i < (int)s.size(); i++) {
            if (i > 0 && ((s[i] - s[i - 1] + 26) % 26) == 1) run++;
            else run = 1;
            int idx = s[i] - 'a';
            best[idx] = max(best[idx], run);
        }
        int ans = 0;
        for (int v : best) ans += v;
        return ans;
    }
};

